using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BoostLinkEffect", menuName = "Data/Battle/Effects/Hevelius/BoostLink Effect")]
public class BoostLinkEffect : HeveliusLinkEffect
{
	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		UpdateDrawDiceAmount();
		base.Initialize(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		UpdateDrawDiceAmount();
		base.EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		base.RemoveEffect(effectAmount, effectOwner);
		UpdateDrawDiceAmount();
	}

	private void UpdateDrawDiceAmount()
	{
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
		{
			ReferenceSingleton<PlayerDiceHandHolder>.Instance.UpdateDrawDicesAmount(0);
		});
	}
}
